using namespace std;

static char buf[1 << 16];
static size_t blen = 0, bpos = 0;
static inline int gc() {
    if (bpos == blen) {
        blen = fread(buf, 1, sizeof buf, stdin);
        bpos = 0;
        if (!blen) return -1;
    }
    return buf[bpos++];
}

int main() {
    int c = gc();
    while (c != -1 && (c < '0' || c > '9')) c = gc();
    int n = 0;
    while (c >= '0' && c <= '9') { n = n * 10 + (c - '0'); c = gc(); }
    string out;
    for (int w = 0; w < n; w++) {
        while (c != -1 && c <= ' ') c = gc();
        // Each run of L equal letters needs floor(L/2) replacements.
        long long answer = 0, run = 0;
        int last = -1;
        while (c > ' ') {
            if (c == last) run++;
            else { answer += run / 2; run = 1; last = c; }
            c = gc();
