        answer += run / 2;
        if (w) out += ' ';
        out += to_string(answer);
    }
    out += '\n';
    fwrite(out.data(), 1, out.size(), stdout);
}

import java.io.*;

public class Main {
    static final InputStream in = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int gc() throws IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    public static void main(String[] args) throws IOException {
        int c = gc();
        while (c != -1 && (c < '0' || c > '9')) c = gc();
        int n = 0;
        while (c >= '0' && c <= '9') { n = n * 10 + (c - '0'); c = gc(); }
        StringBuilder out = new StringBuilder();
        for (int w = 0; w < n; w++) {
            while (c != -1 && c <= ' ') c = gc();
            // Each run of L equal letters needs floor(L/2) replacements.
            long answer = 0, run = 0;
            int last = -1;
            while (c > ' ') {
                if (c == last) run++;
                else { answer += run / 2; run = 1; last = c; }
                c = gc();
            }
            answer += run / 2;
            if (w > 0) out.append(' ');
            out.append(answer);
        }
        System.out.println(out);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

func main() {
	rd := bufio.NewReaderSize(os.Stdin, 1<<16)
	c, err := rd.ReadByte()
	for err == nil && (c < '0' || c > '9') {
		c, err = rd.ReadByte()
	}
	n := 0
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, err = rd.ReadByte()
	}
	var out []byte
	for w := 0; w < n; w++ {
		for err == nil && c <= ' ' {
			c, err = rd.ReadByte()
		}
		// Each run of L equal letters needs floor(L/2) replacements.
		answer, run := 0, 0
		last := -1
		for err == nil && c > ' ' {
			if int(c) == last {
				run++
			} else {
				answer += run / 2
				run, last = 1, int(c)
			}
			c, err = rd.ReadByte()
		}
		answer += run / 2
		if w > 0 {
			out = append(out, ' ')
		}
		out = strconv.AppendInt(out, int64(answer), 10)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
